package EmployeeManagementSystem.service;
import EmployeeManagementSystem.entity.EmployeeComplianceRecord;
import EmployeeManagementSystem.repository.EmployeeComplianceRecordRepository;
import org.springframework.stereotype.Service;
import java.time.*; import java.util.*;
@Service public class EmployeeComplianceRecordServiceImpl implements EmployeeComplianceRecordService{
 private final EmployeeComplianceRecordRepository repo; public EmployeeComplianceRecordServiceImpl(EmployeeComplianceRecordRepository r){repo=r;}
 public List<EmployeeComplianceRecord> my(String u){return repo.findByUserIdOrderByExpiryDateAsc(u);} public List<EmployeeComplianceRecord> all(){return repo.findAllByOrderByExpiryDateAsc();}
 private void validate(EmployeeComplianceRecord x){if(x.getDocumentType()==null||x.getDocumentType().isBlank())throw new IllegalArgumentException("Document type is required.");if(x.getDocumentName()==null||x.getDocumentName().isBlank())throw new IllegalArgumentException("Document name is required.");if(x.getExpiryDate()!=null&&x.getIssueDate()!=null&&x.getExpiryDate().isBefore(x.getIssueDate()))throw new IllegalArgumentException("Expiry date cannot be before issue date.");}
 public EmployeeComplianceRecord create(EmployeeComplianceRecord x,String u,String n){validate(x);if(repo.existsByUserIdAndDocumentTypeAndDocumentNameIgnoreCaseAndStatusIn(u,x.getDocumentType(),x.getDocumentName(),List.of("PENDING_VERIFICATION","VERIFIED")))throw new IllegalArgumentException("An active record with this document type and name already exists.");x.setId(null);x.setRecordNumber("CMP-"+System.currentTimeMillis());x.setUserId(u);x.setEmployeeName(n);x.setStatus("PENDING_VERIFICATION");return repo.save(x);}
 public EmployeeComplianceRecord update(Long id,EmployeeComplianceRecord x,String u,boolean mgmt){EmployeeComplianceRecord e=repo.findById(id).orElseThrow(()->new NoSuchElementException("Compliance record not found."));if(!mgmt&&!u.equals(e.getUserId()))throw new SecurityException("Access denied.");validate(x);e.setDocumentType(x.getDocumentType());e.setDocumentName(x.getDocumentName());e.setDocumentNumber(x.getDocumentNumber());e.setIssueDate(x.getIssueDate());e.setExpiryDate(x.getExpiryDate());e.setIssuingAuthority(x.getIssuingAuthority());e.setDocumentReference(x.getDocumentReference());e.setNotes(x.getNotes());if(!mgmt){e.setStatus("PENDING_VERIFICATION");e.setReviewerUserId(null);e.setReviewerComment(null);e.setVerifiedAt(null);}return repo.save(e);}
 public void delete(Long id,String u,boolean mgmt){EmployeeComplianceRecord e=repo.findById(id).orElseThrow(()->new NoSuchElementException("Compliance record not found."));if(!mgmt&&!u.equals(e.getUserId()))throw new SecurityException("Access denied.");repo.delete(e);}
 public EmployeeComplianceRecord review(Long id,String u,String status,String comment){EmployeeComplianceRecord e=repo.findById(id).orElseThrow(()->new NoSuchElementException("Compliance record not found."));if(!Set.of("VERIFIED","REJECTED").contains(status))throw new IllegalArgumentException("Review status must be VERIFIED or REJECTED.");e.setStatus(status);e.setReviewerUserId(u);e.setReviewerComment(comment);e.setVerifiedAt("VERIFIED".equals(status)?LocalDateTime.now():null);return repo.save(e);}
}
